args.command:
cd /tmp/t10 && for body in "breaks:" "breaking" "BREAKING:" "breaks:x" "breaking-change" "breakage" "breakingnews" "abreaks" "breaks" "BREAKS"; do echo "$RANDOM z" >> f; git add f; git commit -q -F - <<< "fix(p$RANDOM): probe

$body"; done; /workspace/executable -T json 2>/dev/null | sed 's/changelog written.*//' | python3 -c "
import json,sys,re
raw=sys.stdin.read()
raw=re.sub(r'Some\((\".*?\")\)', r'\1', raw).replace(':None',':null')
d=json.loads(raw)
for s in d['sections']:
    if s['title']=='Bug Fixes':
        for c in s['commits'][-10:]: print(repr(c['subject']), 'breaks=',c['breaks'])
"

